{
  "id": 30,
  "knowledge": "Scan Time Efficiency (STE)",
  "description": "Measures how efficiently scanning time was used relative to data quality and completeness metrics.",
  "definition": "STE = \\frac{SQS \\times \\sqrt{CoverPct}}{SpanMin \\times \\sqrt{ScanCount}}, \\text{ where SQS is the Scan Quality Score and higher STE values indicate more efficient use of scanning time relative to coverage achieved.}"
}

{
  "id": 33,
  "knowledge": "Registration Accuracy Ratio (RAR)",
  "description": "Evaluates registration accuracy relative to scan resolution using propagation of uncertainty principles.",
  "definition": "RAR = \\frac{ScanResolMm}{LogAccuMm \\times \\sqrt{1 + \\frac{ErrValMm}{LogAccuMm}}}, \\text{ where values > 1 indicate registration accuracy exceeds scan resolution, a desirable outcome for precise spatial analysis.}"
}

{
  "id": 34,
  "knowledge": "Spatial Density Index (SDI)",
  "description": "Assesses point cloud density relative to site dimensions for spatial sampling adequacy.",
  "definition": "SDI = \\frac{TotalPts}{AreaM2 \\times 10^4} \\times \\left(\\frac{PointDense}{CloudDense}\\right)^{0.5}"
}

{
  "id": 35,
  "knowledge": "Conservation Priority Index (CPI)",
  "description": "Quantifies the urgency of conservation efforts based on site condition, historical significance and structural stability.",
  "definition": "CPI = \\begin{cases} 100 - PS + AF \\times \\left(1 + \\frac{TS}{10}\\right), & \\text{if in a Degradation Risk Zone} \\\\ 50 - PS + AF \\times \\left(1 + \\frac{TS}{20}\\right), & \\text{otherwise} \\end{cases}, \\text{ where PS is 0-100 based on PresStat condition ('Excellent'=10, 'Good'=30, 'Fair'=50, 'Poor'=70, 'Critical'=90), AF is approximate age in millennia derived from GuessDate, and TS is 0-10 based on TypeSite rarity.}"
}

{
  "id": 36,
  "knowledge": "Mesh-to-Point Ratio (MPR)",
  "description": "Evaluates the efficiency of mesh generation from point cloud data for optimal decimation determination.",
  "definition": "MPR = \\frac{FacetVerts}{TotalPts} \\times 100 \\times \\left(\\frac{MCR}{10}\\right)^{0.3}, \\text{ where MCR is the Mesh Complexity Ratio and values around 25-30 indicate optimal decimation for archaeological purposes with appropriate feature preservation.}"
}

{
  "id": 37,
  "knowledge": "Processing Resource Utilization (PRU)",
  "description": "Measures the efficiency of computing resource utilization during scan processing relative to data complexity.",
  "definition": "PRU = \\frac{FlowHrs \\times (ProcCPU + ProcGPU) / 2}{GBSize \\times 10 \\times \\log_{10}(FacetVerts + 10^4)}, \\text{ where lower values indicate more efficient use of computing resources relative to mesh complexity.}"
}

{
  "id": 38,
  "knowledge": "Digital Preservation Quality (DPQ)",
  "description": "Comprehensive metric for evaluating digital preservation quality for archaeological sites with weighted quality factors.",
  "definition": "DPQ = (0.3 \\times ADC) + (0.3 \\times MFS) + (0.2 \\times RAR) + (0.2 \\times SCE) - 2 \\times \\sqrt{\\frac{ErrValMm}{ScanResolMm}}, \\text{ where ADC is Archaeological Documentation Completeness, MFS is Model Fidelity Score, RAR is Registration Accuracy Ratio, and SCE is Scan Coverage Effectiveness.}"
}

{
  "id": 39,
  "knowledge": "Equipment Effectiveness Ratio (EER)",
  "description": "Evaluates how effectively equipment was utilized based on power consumption and scan quality relative to equipment capability.",
  "definition": "EER = \\frac{SQS \\times EquipStatus\\_value}{PowerLevel \\times (101 - EquipAge\\_days) / 365} \\times 25, \\text{ where SQS is the Scan Quality Score, EquipStatus_value is 1.0 for 'Excellent' to 0.2 for 'Poor', and EquipAge_days is days since EquipTune, with higher values indicating more efficient use of equipment relative to condition.}"
}

{
  "id": 40,
  "knowledge": "Spatially Complex Site",
  "description": "Defines sites with complex spatial characteristics requiring specialized scanning approaches based on dimensional analysis.",
  "definition": "A site with AreaM2 > 100 and SDI > 50, where SDI is the Spatial Density Index, requiring strategic planning for comprehensive documentation with multiple scanning stations and methodologies to capture complex spatial relationships."
}

{
  "id": 41,
  "knowledge": "Texture-Critical Artifact",
  "description": "Identifies artifacts where texture documentation is critical for analysis based on surface morphology characteristics.",
  "definition": "Features with TextureStudy containing 'Detailed' or 'Critical' and TDI > 8.0, where TDI is the Texture Density Index, requiring specialized imaging techniques such as photometric stereo or multi-spectral imaging for complete surface characterization."
}

{
  "id": 42,
  "knowledge": "Conservation Emergency",
  "description": "Identifies sites requiring immediate conservation intervention based on multiple risk factors and structural assessment.",
  "definition": "A site that is in a Degradation Risk Zone with CPI > 75, where CPI is the Conservation Priority Index, requiring immediate protective measures and priority documentation with at least Premium Quality Scans before any intervention to establish baseline condition."
}

{
  "id": 43,
  "knowledge": "Processing Optimized Workflow",
  "description": "Defines optimized processing workflows balancing quality and resource use through benchmarked performance metrics.",
  "definition": "A processing workflow with PRU < 5.0 while maintaining MFS > 7.0, where PRU is Processing Resource Utilization and MFS is Model Fidelity Score, representing an efficient balance of resource use and output quality through optimized algorithm selection and hardware allocation."
}

{
  "id": 44,
  "knowledge": "Registration Confidence Level",
  "description": "Classification system for registration confidence based on multiple factors and error propagation analysis.",
  "definition": "A classification where 'High Confidence' registrations have RAR > 1.5 and LogMethod containing 'Target', where RAR is Registration Accuracy Ratio, 'Medium Confidence' have RAR between 1.0-1.5, and 'Low Confidence' have RAR < 1.0, determining appropriate use cases for spatial analysis and interpretive visualization."
}

{
  "id": 45,
  "knowledge": "Environmental Challenge Scan",
  "description": "Identifies scans conducted under challenging environmental conditions requiring expertise and specialized equipment adaptation.",
  "definition": "A scan with EIF > 120, where EIF is Environmental Impact Factor, indicating successful data capture despite suboptimal environmental conditions through adaptive scanning methodologies and operator expertise in field condition compensation."
}

{
  "id": 46,
  "knowledge": "High Temporal Value Site",
  "description": "Identifies sites with exceptional historical significance based on age and context for prioritized research attention.",
  "definition": "A site with GuessDate containing dates before 500 CE and CPI > 60, where CPI is Conservation Priority Index, representing locations of exceptional chronological significance requiring specialized documentation protocols to capture temporally significant features."
}

{
  "id": 47,
  "knowledge": "Resource-Intensive Model",
  "description": "Identifies 3D models requiring substantial computing resources for visualization and analysis based on complexity metrics.",
  "definition": "A model with FacetFaces > 2,000,000 and MPR < 15, where MPR is Mesh-to-Point Ratio, requiring specialized hardware for effective interaction and analytical software optimized for large-scale geometric processing with hierarchical level-of-detail implementation."
}

{
  "id": 48,
  "knowledge": "Multi-Phase Documentation Project",
  "description": "Defines complex archaeological projects requiring multiple scanning phases with integrated documentation strategy.",
  "definition": "A project with multiple scans where the total ADC < 70 for individual scans but DPQ > 80 when combined, where ADC is Archaeological Documentation Completeness and DPQ is Digital Preservation Quality, indicating comprehensive documentation achieved through multiple phases with coherent registration strategy for holistic interpretation."
}

{
  "id": 49,
  "knowledge": "Equipment Optimization Opportunity",
  "description": "Identifies scenarios where equipment settings could be optimized for better results based on performance analysis.",
  "definition": "Scanning scenarios where EER < 30 but ESI > 80, where EER is Equipment Effectiveness Ratio and ESI is Environmental Suitability Index, indicating potential for improved equipment utilization in favorable conditions through calibration adjustment and scanning parameter optimization."
}

{
  "id": 50,
  "knowledge": "Environmental Condition Classification System (ECCS)",
  "description": "A comprehensive classification system for archaeological site environments based on their suitability for scanning operations.",
  "definition": "A four-tier classification where 'Optimal Scanning Conditions' have ESI > 85, 'Good Scanning Conditions' have ESI between 70-85, 'Acceptable Scanning Conditions' have ESI between 50-70, and 'Challenging Scanning Conditions' have ESI < 50. This classification guides scanning schedule planning and equipment selection to maximize data quality."
}

{
  "id": 51,
  "knowledge": "Workflow Efficiency Classification",
  "description": "A standardized categorization system for assessing processing workflow efficiency based on Processing Resource Utilization (PRU) values.",
  "definition": "A three-tier classification where 'Optimized' workflows have PRU < 5.0 (highly efficient resource usage), 'Acceptable' workflows have PRU between 5.0-10.0 (reasonable efficiency), and 'Needs Optimization' workflows have PRU > 10.0 (inefficient resource usage requiring intervention). This classification guides processing workflow improvements and resource allocation decisions."
}

{
  "id": 52,
  "knowledge": "Risk Zone Category",
  "description": "Classification system that evaluates archaeological sites for degradation risk based on preservation status and structural condition.",
  "definition": "Categorizes archaeological sites into two main groups: 'Degradation Risk Zone' and 'Not in Risk Zone'. 'Not in Risk Zone' means that the site is not in a Degradation Risk Zone."
}

{
  "id": 53,
  "knowledge": "Mesh Quality Classification",
  "description": "A standardized system for categorizing archaeological site documentation based on the presence and quality of 3D mesh models.",
  "definition": "A three-tier classification where 'Has High-Fidelity Meshes' indicates sites with at least one mesh meeting high-fidelity criteria, 'Standard Mesh Quality' indicates sites with meshes that don't meet high-fidelity standards, and 'No Mesh Data' indicates sites lacking 3D mesh documentation entirely. This classification helps prioritize additional documentation efforts and determines appropriate analytical approaches for different sites."
}

